import{_ as t,o as e,c as o,aj as i}from"./framework.js";const g=JSON.parse('{"title":"k.paramConfig | Api / Param Config | Documentation","description":"k.paramConfig 读取后台 内容 → 参数配置 中保存的数据：每条配置有 名称（name）、显示名、Schema（字段结构）与 data（JSON 值）。在 Page、Layout、View 或 KScript 中按配置名与字段名访问，无需把电话、开关、链接对象等写死在模板里。","frontmatter":{"title":"k.paramConfig | Api / Param Config | Documentation","description":"k.paramConfig 读取后台 内容 → 参数配置 中保存的数据：每条配置有 名称（name）、显示名、Schema（字段结构）与 data（JSON 值）。在 Page、Layout、View 或 KScript 中按配置名与字段名访问，无需把电话、开关、链接对象等写死在模板里。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/api/param-config/index.html"}]]},"headers":[],"relativePath":"zh/api/param-config/index.md","filePath":"api/param-config/index.md","lastUpdated":1780369368000}'),n={name:"zh/api/param-config/index.md"};function s(r,a,d,c,l,h){return e(),o("div",null,[...a[0]||(a[0]=[i(`<h1 id="k-paramconfig" tabindex="-1">k.paramConfig <a class="header-anchor" href="#k-paramconfig" aria-label="Permalink to &quot;k.paramConfig&quot;">​</a></h1><blockquote><p>读取后台 <strong>内容 → 参数配置</strong> 中保存的结构化 JSON 数据</p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><code>k.paramConfig</code> 读取后台 <strong>内容 → 参数配置</strong> 中保存的数据：每条配置有 <strong>名称</strong>（<code>name</code>）、<strong>显示名</strong>、<strong>Schema</strong>（字段结构）与 <strong>data</strong>（JSON 值）。在 Page、Layout、View 或 KScript 中按配置名与字段名访问，无需把电话、开关、链接对象等写死在模板里。</p><p>后台维护方式见 <a href="/kb-docs/zh/cms/content/user-options.html">参数配置</a>。</p><div class="tip custom-block"><p class="custom-block-title">与其它 API 的区别</p><table tabindex="0"><thead><tr><th>API</th><th>用途</th></tr></thead><tbody><tr><td><strong><code>k.paramConfig</code></strong></td><td>本页：按 Schema 定义的站点级 JSON 参数</td></tr><tr><td><strong><code>k.label</code> / <code>k.t</code></strong></td><td>多语言短文案，见 <a href="/kb-docs/zh/api/label/">k.label</a></td></tr><tr><td><strong><code>k.content</code></strong></td><td>内容夹条目字段，见 <a href="/kb-docs/zh/api/content/">k.content</a></td></tr><tr><td><strong>元素属性（KConfig）</strong></td><td>模板 <code>k-config</code> 绑定的 HTML 属性，见 <a href="/kb-docs/zh/cms/content/tag-attributes.html">元素属性</a></td></tr></tbody></table></div><h2 id="访问方式" tabindex="-1">访问方式 <a class="header-anchor" href="#访问方式" aria-label="Permalink to &quot;访问方式&quot;">​</a></h2><h3 id="属性访问-推荐" tabindex="-1">属性访问（推荐） <a class="header-anchor" href="#属性访问-推荐" aria-label="Permalink to &quot;属性访问（推荐）&quot;">​</a></h3><p>配置在后台的 <strong>名称</strong> 作为 <code>k.paramConfig</code> 的一级属性；Schema 中的字段名作为其下的属性（对象可继续嵌套）。</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 配置名 siteContact，Schema 含 phone、showBanner</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> phone </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> k.paramConfig.siteContact.phone;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> show </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> k.paramConfig.siteContact.showBanner;</span></span></code></pre></div><p>引擎会为当前站点的各配置生成 <strong>KDefine</strong> 类型定义，<code>k.paramConfig</code> 下可按配置名、字段名获得智能提示。</p><h2 id="数据形状" tabindex="-1">数据形状 <a class="header-anchor" href="#数据形状" aria-label="Permalink to &quot;数据形状&quot;">​</a></h2><ul><li><strong>Schema</strong> 在后台定义，支持 <code>string</code>、<code>number</code>、<code>boolean</code>、<code>object</code>、<code>array</code>（及嵌套）。</li><li><strong>data</strong> 须与 Schema 一致；在后台 <strong>编辑数据</strong> 页或 JSON 编辑器中维护。</li><li>数组、嵌套对象的访问方式与普通 JavaScript 对象相同，例如 <code>k.paramConfig.footer.links[0].url</code>。</li></ul><h2 id="不存在或未填值时" tabindex="-1">不存在或未填值时 <a class="header-anchor" href="#不存在或未填值时" aria-label="Permalink to &quot;不存在或未填值时&quot;">​</a></h2><ul><li>配置名不存在，或该配置尚无 <code>data</code>：属性访问将得到 <strong><code>undefined</code></strong>。</li><li>脚本中应先判断再使用，避免直接访问深层属性时报错。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/kb-docs/zh/cms/content/user-options.html">参数配置（后台）</a></li><li><a href="/kb-docs/zh/api/site/">k.site</a> — 站点资源</li><li><a href="/kb-docs/zh/api/label/">k.label</a> — 多语言标签</li></ul>`,17)])])}const k=t(n,[["render",s]]);export{g as __pageData,k as default};
